class Solution {
  private long[] mx, lazy;

  private void add(int node, int lo, int hi, int l, int r, int v) {
    if (l > r || r < lo || hi < l) return;
    if (l <= lo && hi <= r) {
      mx[node] += v;
      lazy[node] += v;
      return;
    }
    int mid = (lo + hi) >>> 1;
    add(2 * node, lo, mid, l, r, v);
    add(2 * node + 1, mid + 1, hi, l, r, v);
    mx[node] = Math.max(mx[2 * node], mx[2 * node + 1]) + lazy[node];
  }

  public int[] maximumCount(int[] nums, int[][] queries) {
    int n = nums.length, MAXV = 100_000;
    boolean[] composite = new boolean[MAXV + 1];
    composite[0] = composite[1] = true;
    for (int i = 2; (long) i * i <= MAXV; i++)
      if (!composite[i]) for (int j = i * i; j <= MAXV; j += i) composite[j] = true;
    java.util.TreeSet<Integer>[] pos = new java.util.TreeSet[MAXV + 1];
    mx = new long[4 * n];
    lazy = new long[4 * n];
    int[] a = nums.clone();
    for (int i = 0; i < n; i++) {
      if (composite[a[i]]) continue;
      if (pos[a[i]] == null) pos[a[i]] = new java.util.TreeSet<>();
      pos[a[i]].add(i);
    }
    for (int p = 2; p <= MAXV; p++) if (pos[p] != null) apply(pos[p], n, 1);
    int[] ans = new int[queries.length];
    for (int qi = 0; qi < queries.length; qi++) {
      int idx = queries[qi][0], val = queries[qi][1];
      int old = a[idx];
      if (!composite[old]) {
        apply(pos[old], n, -1);
        pos[old].remove(idx);
        if (!pos[old].isEmpty()) apply(pos[old], n, 1);
      }
      a[idx] = val;
      if (!composite[val]) {
        if (pos[val] == null) pos[val] = new java.util.TreeSet<>();
        if (!pos[val].isEmpty()) apply(pos[val], n, -1);
        pos[val].add(idx);
        apply(pos[val], n, 1);
      }
      ans[qi] = (int) mx[1];
    }
    return ans;
  }

  // split k in [1, n-1]: prefix has prime iff k > first; suffix has prime iff k <= last
  private void apply(java.util.TreeSet<Integer> set, int n, int sign) {
    int first = set.first(), last = set.last();
    add(1, 1, n - 1, first + 1, n - 1, sign);
    add(1, 1, n - 1, 1, last, sign);
  }
}
